  "授权完成，请刷新页面后建立新的 P2P 连接": {
    "zh-Hant": "授權完成，請重新整理頁面後建立新的 P2P 連線",
    "en": "Permission granted. Refresh the page before creating new P2P connections.",
    "ja": "許可されました。ページを再読み込みしてから新しい P2P 接続を確立してください。",
    "fr": "Autorisation accordée. Actualisez la page avant d’établir de nouvelles connexions P2P.",
    "ru": "Разрешение получено. Обновите страницу перед созданием новых P2P-соединений.",
    "es": "Permiso concedido. Actualiza la página antes de crear nuevas conexiones P2P.",
    "it": "Autorizzazione concessa. Aggiorna la pagina prima di creare nuove connessioni P2P.",
    "ko": "권한이 허용되었습니다. 새 P2P 연결을 만들기 전에 페이지를 새로고침하세요.",
    "ms": "Kebenaran diberikan. Muat semula halaman sebelum membuat sambungan P2P baharu.",
    "id": "Izin diberikan. Muat ulang halaman sebelum membuat koneksi P2P baru.",
    "vi": "Đã cấp quyền. Hãy tải lại trang trước khi tạo kết nối P2P mới.",
    "th": "ให้สิทธิ์แล้ว โปรดรีเฟรชหน้าก่อนสร้างการเชื่อมต่อ P2P ใหม่",
    "fa": "مجوز داده شد؛ صفحه را بازخوانی کنید و اتصال P2P جدیدی بسازید",
    "km": "បានអនុញ្ញាត សូមផ្ទុកទំព័រឡើងវិញដើម្បីបង្កើតការតភ្ជាប់ P2P ថ្មី",
    "my": "ခွင့်ပြုပြီး၊ စာမျက်နှာ ပြန်တင်ကာ P2P အသစ် ချိတ်ဆက်ပါ"
  },
  "授权失败，请在站点设置中允许摄像头和麦克风": {
    "zh-Hant": "授權失敗，請在網站設定中允許攝影機和麥克風",
    "en": "Permission failed. Allow camera and microphone in site settings.",
    "ja": "許可に失敗しました。サイト設定でカメラとマイクを許可してください。",
    "fr": "Échec de l’autorisation. Autorisez la caméra et le microphone dans les paramètres du site.",
    "ru": "Не удалось получить разрешение. Разрешите камеру и микрофон в настройках сайта.",
    "es": "No se pudo obtener permiso. Permite la cámara y el micrófono en la configuración del sitio.",
    "it": "Autorizzazione non riuscita. Consenti fotocamera e microfono nelle impostazioni del sito.",
    "ko": "권한을 얻지 못했습니다. 사이트 설정에서 카메라와 마이크를 허용하세요.",
    "ms": "Kebenaran gagal. Benarkan kamera dan mikrofon dalam tetapan tapak.",
    "id": "Izin gagal. Izinkan kamera dan mikrofon di pengaturan situs.",
    "vi": "Không cấp được quyền. Hãy cho phép máy ảnh và micrô trong cài đặt trang web.",
    "th": "ให้สิทธิ์ไม่สำเร็จ โปรดอนุญาตกล้องและไมโครโฟนในการตั้งค่าไซต์",
    "fa": "مجوز داده نشد؛ در تنظیمات سایت به دوربین و میکروفون اجازه دهید",
    "km": "អនុញ្ញាតបរាជ័យ សូមអនុញ្ញាតកាមេរ៉ា និងមីក្រូហ្វូនក្នុងការកំណត់គេហទំព័រ",
    "my": "ခွင့်ပြုမှု မအောင်မြင်၊ ဆိုက်ဆက်တင်တွင် ကင်မရာနှင့် မိုက်ခရိုဖုန်း ခွင့်ပြုပါ"
  },
  "检测到同一局域网设备或 Socket.IO 中转。授权站点媒体权限可提高局域网 P2P 直连成功率；音视频不会被上传。": {
    "zh-Hant": "偵測到同一區域網路裝置或 Socket.IO 中繼。授予網站媒體權限可提高區域網路 P2P 直連成功率；影音不會被上傳。",
    "en": "A same-LAN device or Socket.IO relay was detected. Site media permission may improve LAN P2P direct connections; no audio or video is uploaded.",
    "ja": "同一 LAN のデバイスまたは Socket.IO リレーを検出しました。サイトのメディア権限を許可すると LAN P2P 直接接続が改善する場合があります。音声や映像は送信されません。",
    "fr": "Un appareil du même réseau local ou un relais Socket.IO a été détecté. L’autorisation multimédia du site peut améliorer la connexion P2P locale ; aucun son ni aucune vidéo n’est envoyé.",
    "ru": "Обнаружено устройство в той же локальной сети или ретрансляция Socket.IO. Разрешение на мультимедиа может улучшить прямое P2P-соединение; аудио и видео не передаются.",
    "es": "Se detectó un dispositivo en la misma LAN o un relé Socket.IO. El permiso multimedia del sitio puede mejorar la conexión P2P local; no se sube audio ni vídeo.",
    "it": "È stato rilevato un dispositivo nella stessa LAN o un relay Socket.IO. Il permesso multimediale del sito può migliorare la connessione P2P locale; audio e video non vengono caricati.",
    "ko": "동일 LAN 기기 또는 Socket.IO 릴레이가 감지되었습니다. 사이트 미디어 권한은 LAN P2P 직접 연결 성공률을 높일 수 있으며 음성이나 영상은 업로드되지 않습니다.",
    "ms": "Peranti pada LAN yang sama atau geganti Socket.IO dikesan. Kebenaran media tapak boleh meningkatkan sambungan terus P2P LAN; audio dan video tidak dimuat naik.",
    "id": "Perangkat di LAN yang sama atau relay Socket.IO terdeteksi. Izin media situs dapat meningkatkan koneksi langsung P2P LAN; audio dan video tidak diunggah.",
    "vi": "Đã phát hiện thiết bị cùng LAN hoặc chuyển tiếp Socket.IO. Quyền media của trang có thể cải thiện kết nối P2P trực tiếp trong LAN; âm thanh và video không được tải lên.",
    "th": "ตรวจพบอุปกรณ์ใน LAN เดียวกันหรือการส่งต่อ Socket.IO การอนุญาตสื่อของเว็บไซต์อาจช่วยเพิ่มโอกาสเชื่อมต่อ P2P โดยตรง และจะไม่มีการอัปโหลดเสียงหรือวิดีโอ",
    "fa": "دستگاه شبکهٔ محلی یا رلهٔ Socket.IO شناسایی شد. مجوز رسانهٔ سایت می‌تواند اتصال مستقیم P2P را بهبود دهد؛ صدا و ویدئو بارگذاری نمی‌شود.",
    "km": "រកឃើញឧបករណ៍បណ្ដាញមូលដ្ឋាន ឬបញ្ជូនបន្ត Socket.IO។ អនុញ្ញាតមេឌៀគេហទំព័រអាចបង្កើនការតភ្ជាប់ P2P ផ្ទាល់ មិនផ្ទុកសំឡេង ឬវីដេអូឡើងទេ។",
    "my": "ဒေသတွင်းကွန်ရက်စက် သို့မဟုတ် Socket.IO ကြားခံ တွေ့ရှိသည်။ ဆိုက်မီဒီယာခွင့်က P2P တိုက်ရိုက်ချိတ်ဆက်မှု ပိုကောင်းစေနိုင်ပြီး အသံ/ဗီဒီယိုကို မတင်ပါ။"
  },
