    "my": "မူလဝဘ်စာမျက်နှာ ဆက်နွယ်မှု မစစ်ဆေးရသေးပါ။ မူကြမ်းကို ထိန်းပြီး မူလမှတ်တမ်း သို့မဟုတ် တည်းဖြတ်ခွင့်အထောက်အထား စစ်ပါ။"
